// Output audit against the running production server; uses synthetic prices, never official data.
// Excel is opened and recalculated in LibreOffice Calc when available; PDF is generated by Chromium print.
import assert from "node:assert/strict";
import { chromium } from "playwright";
import ExcelJS from "exceljs";
import JSZip from "jszip";
import { mkdtempSync, mkdirSync, readFileSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { spawnSync } from "node:child_process";

const base = process.env.SMOKE_BASE || "http://127.0.0.1:3000";
const tmp = mkdtempSync(join(tmpdir(), "metra-output-"));
let cookie = "";
async function request(path, method = "GET", body) {
  const headers = {};
  if (cookie) headers.Cookie = cookie;
  if (body !== undefined) headers["Content-Type"] = "application/json";
  const response = await fetch(base + path, { method, headers, body: body === undefined ? undefined : JSON.stringify(body) });
  const nextCookie = response.headers.get("set-cookie")?.match(/metra_session=[^;]+/)?.[0];
  if (nextCookie) cookie = nextCookie;
  return response;
}
async function json(path, method = "GET", body, expected = 200) {
  const response = await request(path, method, body);
  const parsed = await response.json().catch(() => ({}));
  assert.equal(response.status, expected, `${method} ${path}: ${JSON.stringify(parsed).slice(0, 230)}`);
  return parsed;
}
function command(name, args) {
  const result = spawnSync(name, args, { encoding: "utf8", timeout: 120000, env: { ...process.env, HOME: tmp } });
  if (result.error || result.status !== 0) throw new Error(`${name} failed: ${String(result.error || result.stderr || result.stdout).slice(0, 350)}`);
  return result.stdout;
}

try {
  await json("/api/workspace");
  const project = (await json("/api/projects", "POST", { name: "پروژه خروجی آزمون (آموزشی)", type: "مسکونی", floors: 2,
    basements: 1, fundingType: "private", pricingBasis: "market", stage: "detailed", estimateDate: "1404/02/01" }, 201)).project;
  const dimensions = ["0.1", "0.2", "0.3"];
  const quantities = ["0.6000", "1.2000", "1.8000"];
  const price = (await json("/api/prices", "POST", { title: "بهای نمونه غیرواقعی", unit: "مترمکعب", basis: "market", amount: "5000",
    currency: "IRR", sourceName: "داده آزمون (غیرواقعی)", priceDate: "1404/02/01", confirmed: true }, 201)).item;
  for (let i = 0; i < dimensions.length; i++) {
    const row = (await json("/api/takeoffs", "POST", { projectId: project.id, title: i === 2 ? '=HYPERLINK("unsafe")' : `حجم نمونه ${i + 1}`, category: "بتن‌ریزی",
      kind: "volume", length: "2", width: "3", height: dimensions[i], count: "1", floor: `طبقه ${i + 1}`,
      location: `محور ${i + 1}`, sourceNote: `ابعاد آزمایشی ${i + 1}` }, 201)).item;
    assert.equal(row.quantity, quantities[i]);
    await json("/api/takeoffs", "PATCH", { id: row.id, action: "assignPrice", priceId: price.id });
    await json("/api/takeoffs", "PATCH", { id: row.id, action: "confirm" });
  }
  const snapshot = (await json("/api/estimates", "POST", { projectId: project.id, notes: "خروجی آزمایشی" }, 201)).snapshot;
  assert.equal(snapshot.totalRial, "18000");
  const prefix = `/api/export?projectId=${project.id}&snapshotId=${snapshot.id}&format=`;
  const frozen = await json(prefix + "json");
  assert.equal(frozen.snapshot.rows.length, 3);
  assert.deepEqual(frozen.snapshot.rows.map((row) => row.amountRial).sort((a, b) => Number(a) - Number(b)), ["3000", "6000", "9000"]);
  const csvResponse = await request(prefix + "csv");
  assert.equal(csvResponse.status, 200);
  const csvBytes = Buffer.from(await csvResponse.arrayBuffer());
  assert(csvBytes.subarray(0, 3).equals(Buffer.from([0xef, 0xbb, 0xbf])), "CSV needs UTF-8 BOM for Persian Excel import");
  const csv = csvBytes.toString("utf8");
  assert(csv.includes('"18000"') && csv.includes('"9000"'));
  assert(csv.includes(`"'=HYPERLINK(""unsafe"")"`), "CSV must neutralize formula-like text");
  console.log("✓ JSON/CSV: frozen version, Rial units, exact row amounts, UTF-8 BOM");

  const xlsxResponse = await request(prefix + "xlsx");
  assert.equal(xlsxResponse.status, 200);
  const xlsx = Buffer.from(await xlsxResponse.arrayBuffer());
  assert.equal(xlsx.subarray(0, 2).toString(), "PK", "Excel must be a valid ZIP container");
  const workbook = new ExcelJS.Workbook();
  await workbook.xlsx.load(xlsx);
  assert.equal(workbook.worksheets.length, 2);
  const estimate = workbook.getWorksheet("برآورد");
  assert(estimate?.views[0]?.rightToLeft);
  const seenAmounts = [];
  for (let i = 0; i < 3; i++) {
    const line = i + 5;
    const qty = estimate.getCell(`D${line}`).value;
    assert([0.6, 1.2, 1.8].includes(qty));
    assert.equal(estimate.getCell(`E${line}`).value, 5000);
    assert.equal(estimate.getCell(`F${line}`).value.formula, `ROUND(D${line}*E${line},0)`);
    assert.equal(estimate.getCell(`F${line}`).value.result, qty * 5000);
    seenAmounts.push(estimate.getCell(`F${line}`).value.result);
  }
  assert.deepEqual(seenAmounts.sort((a, b) => a - b), [3000, 6000, 9000]);
  assert.equal(estimate.getCell("F8").value.formula, "SUM(F5:F7)");
  assert.equal(estimate.getCell("F8").value.result, 18000);
  const archive = await JSZip.loadAsync(xlsx);
  const workbookXml = await archive.file("xl/workbook.xml").async("string");
  assert.match(workbookXml, /fullCalcOnLoad="1"/);
  const takeoffResponse = await request(`/api/export/takeoff?projectId=${project.id}`);
  assert.equal(takeoffResponse.status, 200);
  const takeoffBytes = Buffer.from(await takeoffResponse.arrayBuffer());
  const takeoffBook = new ExcelJS.Workbook();
  await takeoffBook.xlsx.load(takeoffBytes);
  assert.equal(takeoffBook.worksheets.length, 3);
  const detail = takeoffBook.getWorksheet("ریزمتره");
  const summary = takeoffBook.getWorksheet("خلاصه متره");
  assert(detail?.views[0]?.rightToLeft && summary?.views[0]?.rightToLeft);
  assert.deepEqual([5, 6, 7].map((n) => detail.getCell(`H${n}`).value.result).sort((a, b) => a - b), [0.6, 1.2, 1.8]);
  assert(summary.getCell("C5").value.formula.startsWith("SUMPRODUCT("));
  assert.equal(summary.getCell("C5").value.result, 3.6);
  console.log("✓ ExcelJS: both XLSX files parsed, real formulas and cached results match independent arithmetic");

  // Wildcards and case distinctions must not merge different categories in the recalculated workbook.
  const specialProject = (await json("/api/projects", "POST", { name: "آزمون دسته‌بندی دقیق", type: "مسکونی", floors: 1,
    basements: 0, fundingType: "private", pricingBasis: "market", stage: "detailed" }, 201)).project;
  for (const [category, count] of [["A*", "2"], ["Ab", "3"], ["ab", "4"]]) {
    await json("/api/takeoffs", "POST", { projectId: specialProject.id, title: `ردیف ${category}`, category,
      kind: "count", count, sourceNote: "داده آزمون" }, 201);
  }
  const specialResponse = await request(`/api/export/takeoff?projectId=${specialProject.id}`);
  assert.equal(specialResponse.status, 200);
  const specialBook = new ExcelJS.Workbook();
  await specialBook.xlsx.load(Buffer.from(await specialResponse.arrayBuffer()));
  const specialSummary = specialBook.getWorksheet("خلاصه متره");
  for (const [category, amount] of [["A*", 2], ["Ab", 3], ["ab", 4]]) {
    const row = specialSummary.getRows(5, 3).find((r) => r.getCell(1).value === category);
    assert(row && row.getCell(4).value.result === amount);
    assert.match(row.getCell(4).value.formula, /EXACT\(/);
  }
  console.log("✓ summary formulas use exact, case-sensitive category and unit matching");

  const estimatedFile = join(tmp, "estimate.xlsx");
  const takeoffFile = join(tmp, "takeoff.xlsx");
  writeFileSync(estimatedFile, xlsx);
  writeFileSync(takeoffFile, takeoffBytes);
  if (spawnSync("which", ["soffice"]).status === 0) {
    const args = ["-env:UserInstallation=file://" + join(tmp, "lo-profile"), "--headless", "--convert-to", "csv", "--outdir", tmp];
    command("soffice", [...args, estimatedFile]);
    command("soffice", [...args, takeoffFile]);
    const loEstimate = readFileSync(join(tmp, "estimate.csv"), "utf8");
    const loTakeoff = readFileSync(join(tmp, "takeoff.csv"), "utf8");
    assert(loEstimate.includes(",3000,") && loEstimate.includes(",6000,") && loEstimate.includes(",9000,"));
    assert(loEstimate.includes(",18000"), "LibreOffice must recalculate the estimate total");
    assert(loTakeoff.includes(",0.6,") && loTakeoff.includes(",1.2,") && loTakeoff.includes(",1.8,"),
      "LibreOffice must recalculate the takeoff detail sheet");
    const recalculatedDir = join(tmp, "recalculated");
    mkdirSync(recalculatedDir);
    command("soffice", ["-env:UserInstallation=file://" + join(tmp, "lo-profile-recalc"), "--headless",
      "--convert-to", "xlsx", "--outdir", recalculatedDir, takeoffFile]);
    const recalculated = new ExcelJS.Workbook();
    await recalculated.xlsx.load(readFileSync(join(recalculatedDir, "takeoff.xlsx")));
    assert.equal(recalculated.getWorksheet("خلاصه متره").getCell("C5").value.result, 3.6,
      "LibreOffice must recalculate SUMPRODUCT in the takeoff summary sheet");
    console.log("✓ LibreOffice Calc: opened both XLSX files and recalculated detail, financial and summary formulas");
  } else console.log("NOT RUN: LibreOffice not installed; native XLSX-opening test unavailable");

  const browser = await chromium.launch();
  try {
    const context = await browser.newContext({ locale: "fa-IR" });
    await context.addCookies([{ name: "metra_session", value: cookie.split("=")[1], url: base }]);
    for (const [route, label] of [[`/report/${snapshot.id}`, "estimate"], [`/report/takeoff/${project.id}`, "takeoff"]]) {
      const page = await context.newPage();
      const response = await page.goto(base + route, { waitUntil: "networkidle" });
      assert.equal(response.status(), 200);
      await page.locator(".report-page").waitFor();
      assert.equal(await page.locator("html").getAttribute("dir"), "rtl");
      await page.emulateMedia({ media: "print" });
      assert(await page.locator(".report-tools").isHidden());
      const pdf = await page.pdf({ format: "A4", printBackground: true });
      assert.equal(pdf.subarray(0, 4).toString(), "%PDF");
      const path = join(tmp, label + ".pdf");
      writeFileSync(path, pdf);
      if (spawnSync("which", ["pdfinfo"]).status === 0) {
        const info = command("pdfinfo", [path]);
        const pages = Number(info.match(/^Pages:\s+(\d+)/m)?.[1]);
        assert(pages >= 1 && pages <= 10, `${label} PDF must have reasonable page count`);
        const text = command("pdftotext", ["-layout", path, "-"]);
        assert(text.includes("18000") || text.includes("۱۸٬۰۰۰") || label === "takeoff", `${label} PDF must contain the calculated total`);
        console.log(`✓ ${label} PDF: valid PDF, ${pages} page(s), printable RTL report`);
      } else if (spawnSync("python3", ["-c", "import pypdf"], { env: process.env }).status === 0) {
        const text = command("python3", ["-c", "import sys; from pypdf import PdfReader; p=PdfReader(sys.argv[1]); assert 1 <= len(p.pages) <= 10; print('\\n'.join(x.extract_text() for x in p.pages))", path]);
        assert(text.length > 100, `${label} PDF must have extractable content`);
        if (label === "estimate") assert(/۱۸[٬,]?۰۰۰|۰۰۰[٬,]?۸۱|18000/.test(text), "estimate PDF must contain the calculated total");
        console.log(`✓ ${label} PDF: parsed pages and extracted report text with pypdf`);
      } else console.log(`NOT RUN: PDF extraction tools unavailable for ${label} PDF`);
      await page.close();
    }
    await context.close();
  } finally { await browser.close(); }
  console.log("NOT IMPLEMENTED: Word/DOCX export — no route, no test, no claim of support");
  console.log("Output check passed.");
} finally {
  rmSync(tmp, { recursive: true, force: true });
}
